+	settingsPath := filepath.Join(env.RepoDir, ".entire", "settings.json")
+	if err := os.WriteFile(settingsPath, []byte("{\n  \"enabled\": true\n}\n"), 0o644); err != nil {
+		t.Fatalf("failed to write non-local-dev settings: %v", err)
