package copilotcli

import (
	"context"
	"fmt"
	"io"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/logging"
)

// Ensure CopilotCLIAgent implements HookSupport at compile time.
var _ agent.HookSupport = (*CopilotCLIAgent)(nil)

// Copilot CLI hook names - these become subcommands under `entire hooks copilot-cli`
const (
	HookNameUserPromptSubmitted = "user-prompt-submitted"
	HookNameSessionStart        = "session-start"
	HookNameAgentStop           = "agent-stop"
	HookNameSessionEnd          = "session-end"
	HookNameSubagentStop        = "subagent-stop"
	HookNamePreToolUse          = "pre-tool-use"
	HookNamePostToolUse         = "post-tool-use"
	HookNameErrorOccurred       = "error-occurred"
)

// HookNames returns all hook verbs Copilot CLI supports.
// These become subcommands: entire hooks copilot-cli <verb>
func (c *CopilotCLIAgent) HookNames() []string {
	return []string{
		HookNameUserPromptSubmitted,
		HookNameSessionStart,
		HookNameAgentStop,
		HookNameSessionEnd,
		HookNameSubagentStop,
		HookNamePreToolUse,
		HookNamePostToolUse,
		HookNameErrorOccurred,
	}
}

// ParseHookEvent translates a Copilot CLI hook into a normalized lifecycle Event.
// Returns nil if the hook has no lifecycle significance (pass-through hooks).
//
// For VS Code payloads (detected via hookEventName), the event name is validated
// against the CLI subcommand. Mismatches are silently skipped to avoid processing
// a payload that doesn't match the hook being invoked.
func (c *CopilotCLIAgent) ParseHookEvent(ctx context.Context, hookName string, stdin io.Reader) (*agent.Event, error) {
	// Pass-through hooks: skip immediately without reading stdin.
	switch hookName {
	case HookNamePreToolUse, HookNamePostToolUse, HookNameErrorOccurred:
		return nil, nil //nolint:nilnil // Pass-through hooks have no lifecycle action
	}

	// For lifecycle hooks, read and parse the envelope first so we can
	// validate VS Code hookEventName before constructing an event.
	env, err := c.readHookEnvelope(stdin)
	if err != nil {
		return nil, err
	}

	// VS Code payloads: validate hookEventName matches the CLI subcommand.
	if env.Host == HostVSCode && env.HookEventName != "" {
		if !validateVSCodeEvent(env.HookEventName, hookName) {
			logging.Debug(ctx, "copilot-cli: skipping VS Code event with mismatched hookEventName",
				"hookEventName", env.HookEventName, "hookName", hookName)
			return nil, nil //nolint:nilnil // Mismatched VS Code event — skip silently.
		}
	}

	switch hookName {
	case HookNameUserPromptSubmitted:
		return c.buildUserPromptSubmitted(ctx, env), nil
	case HookNameSessionStart:
		return c.buildSessionStart(env), nil
	case HookNameAgentStop:
		return c.buildAgentStop(ctx, env), nil
	case HookNameSessionEnd:
		return c.buildSessionEnd(env), nil
	case HookNameSubagentStop:
		return c.buildSubagentStop(env), nil
	default:
		logging.Debug(ctx, "copilot-cli: ignoring unknown hook", "hook", hookName)
		return nil, nil //nolint:nilnil // Unknown hooks have no lifecycle action
	}
}

// --- Internal event builders (envelope already parsed) ---

func (c *CopilotCLIAgent) buildUserPromptSubmitted(ctx context.Context, env *hookEnvelope) *agent.Event {
	transcriptRef := env.TranscriptPath
	if transcriptRef == "" {
		transcriptRef = c.resolveTranscriptRef(ctx, env.SessionID)
	}

	return &agent.Event{
		Type:       agent.TurnStart,
		SessionID:  env.SessionID,
		SessionRef: transcriptRef,
		Prompt:     env.Prompt,
		Timestamp:  env.Timestamp,
	}
}

func (c *CopilotCLIAgent) buildSessionStart(env *hookEnvelope) *agent.Event {
	return &agent.Event{
		Type:      agent.SessionStart,
		SessionID: env.SessionID,
		Timestamp: env.Timestamp,
	}
}

func (c *CopilotCLIAgent) buildAgentStop(ctx context.Context, env *hookEnvelope) *agent.Event {
	var model string
	if env.TranscriptPath != "" {
		model = ExtractModelFromTranscript(ctx, env.TranscriptPath)
	}

	return &agent.Event{
		Type:       agent.TurnEnd,
		SessionID:  env.SessionID,
		SessionRef: env.TranscriptPath,
		Model:      model,
		Timestamp:  env.Timestamp,
	}
}

func (c *CopilotCLIAgent) buildSessionEnd(env *hookEnvelope) *agent.Event {
	return &agent.Event{
		Type:      agent.SessionEnd,
		SessionID: env.SessionID,
		Timestamp: env.Timestamp,
	}
}

func (c *CopilotCLIAgent) buildSubagentStop(env *hookEnvelope) *agent.Event {
	return &agent.Event{
		Type:      agent.SubagentEnd,
		SessionID: env.SessionID,
		Timestamp: env.Timestamp,
	}
}

func (c *CopilotCLIAgent) readHookEnvelope(stdin io.Reader) (*hookEnvelope, error) {
	data, err := io.ReadAll(stdin)
	if err != nil {
		return nil, fmt.Errorf("failed to read hook input: %w", err)
	}
	return parseHookEnvelope(data)
}

// resolveTranscriptRef computes the transcript path from the session ID.
// Copilot CLI stores transcripts at ~/.copilot/session-state/<sessionId>/events.jsonl.
// The userPromptSubmitted hook does not include a transcriptPath field, so we compute it.
func (c *CopilotCLIAgent) resolveTranscriptRef(ctx context.Context, sessionID string) string {
	// GetSessionDir ignores the repoPath parameter for Copilot CLI since session
	// state is always in ~/.copilot/session-state/ (not repo-specific).
	sessionDir, err := c.GetSessionDir("")
	if err != nil {
		logging.Warn(ctx, "copilot-cli: failed to resolve transcript path", "sessionID", sessionID, "err", err)
		return ""
	}
	return c.ResolveSessionFile(sessionDir, sessionID)
}

// handleLifecycleTurnStart handles turn start: captures pre-prompt state,
// ensures strategy setup, initializes session.
func handleLifecycleTurnStart(ctx context.Context, ag agent.Agent, event *agent.Event) error {
	logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
	logging.Info(logCtx, "turn-start",
		slog.String("event", event.Type.String()),
		slog.String("session_id", event.SessionID),
		slog.String("session_ref", event.SessionRef),
		slog.String("model", event.Model),
	)

	sessionID := event.SessionID
	if sessionID == "" {
		return fmt.Errorf("no session_id in %s event", event.Type)
	}
	if err := validation.ValidateSessionID(sessionID); err != nil {
		return fmt.Errorf("invalid %s event: %w", event.Type, err)
	}

	// Fill model from hint file if the agent didn't provide it on this hook
	if event.Model == "" {
		if hint := strategy.LoadModelHint(ctx, sessionID); hint != "" {
			event.Model = hint
			logging.Debug(logCtx, "loaded model from hint file",
				slog.String("model", hint))
		}
	}

	// Capture pre-prompt state (including transcript position via TranscriptAnalyzer)
	_, captureSpan := perf.Start(ctx, "capture_pre_prompt_state")
	if err := CapturePrePromptState(ctx, ag, sessionID, event.SessionRef); err != nil {
		captureSpan.RecordError(err)
		captureSpan.End()
		return err
	}
	captureSpan.End()

	// Append prompt to prompt.txt on filesystem so it's available for
	// mid-turn commits (before SaveStep writes it to the shadow branch).
	// Prompts are separated by "\n\n---\n\n" to support multiple turns.
	if event.Prompt != "" {
		sessionDir := paths.SessionMetadataDirFromSessionID(sessionID)
		if sessionDirAbs, absErr := paths.AbsPath(ctx, sessionDir); absErr == nil {
			if mkErr := os.MkdirAll(sessionDirAbs, 0o750); mkErr == nil {
				promptPath := filepath.Join(sessionDirAbs, paths.PromptFileName)
				existing, readErr := os.ReadFile(promptPath) //nolint:gosec // session metadata path
				var content string
				if readErr == nil && len(existing) > 0 {
					content = string(existing) + "\n\n---\n\n" + event.Prompt
				} else {
					content = event.Prompt
				}
				if writeErr := os.WriteFile(promptPath, []byte(content), 0o600); writeErr != nil { //nolint:gosec // path from internal metadata, not user input
					logging.Warn(logCtx, "failed to write prompt.txt",
						slog.String("error", writeErr.Error()))
				}
			}
		}
	}

	// Ensure strategy setup and initialize session
	_, initSpan := perf.Start(ctx, "init_session")
	if err := strategy.EnsureSetup(ctx); err != nil {
		logging.Warn(logCtx, "failed to ensure strategy setup",
			slog.String("error", err.Error()))
	}

	strat := GetStrategy(ctx)
	if err := strat.InitializeSession(ctx, sessionID, ag.Type(), event.SessionRef, event.Prompt, event.Model); err != nil {
		logging.Warn(logCtx, "failed to initialize session state",
			slog.String("error", err.Error()))
	}
	initSpan.End()

	return nil
}

// handleLifecycleTurnEnd handles turn end: validates transcript, extracts metadata,
// detects file changes, saves step + checkpoint, transitions phase.
//
//nolint:maintidx // high complexity due to sequential orchestration of 8 steps (validation, extraction, file detection, filtering, token calc, step save, phase transition, cleanup) - splitting would obscure the flow
func handleLifecycleTurnEnd(ctx context.Context, ag agent.Agent, event *agent.Event) error {
	logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
	logging.Info(logCtx, "turn-end",
		slog.String("event", event.Type.String()),
		slog.String("session_id", event.SessionID),
		slog.String("session_ref", event.SessionRef),
		slog.String("model", event.Model),
	)

	sessionID := event.SessionID
	if sessionID == "" {
		sessionID = unknownSessionID
	}

	// Fill model from hint file if the agent didn't provide it on this hook
	if event.Model == "" && sessionID != unknownSessionID {
		if hint := strategy.LoadModelHint(ctx, sessionID); hint != "" {
			event.Model = hint
			logging.Debug(logCtx, "loaded model from hint file",
				slog.String("model", hint))
		}
	}

	transcriptRef := event.SessionRef
	if transcriptRef == "" {
		return errors.New("transcript file not specified")
	}

	// If agent implements TranscriptPreparer, materialize the transcript file.
	// This must run BEFORE fileExists: agents like OpenCode lazily fetch transcripts
	// via `opencode export`, so the file doesn't exist until PrepareTranscript creates it.
	// Claude Code's PrepareTranscript just flushes (always succeeds). Agents without
	// TranscriptPreparer (Gemini, Droid) are unaffected.
	_, prepareSpan := perf.Start(ctx, "prepare_and_validate_transcript")
	if preparer, ok := agent.AsTranscriptPreparer(ag); ok {
		if err := preparer.PrepareTranscript(ctx, transcriptRef); err != nil {
			logging.Warn(logCtx, "failed to prepare transcript",
				slog.String("error", err.Error()))
		}
	}

	if !fileExists(transcriptRef) {
		prepareSpan.RecordError(fmt.Errorf("transcript file not found: %s", transcriptRef))
		prepareSpan.End()
		return fmt.Errorf("transcript file not found: %s", transcriptRef)
	}

	// Early check: bail out quickly if the repo has no commits yet.
	// Return nil (not an error) so the hook exits 0 — agents treat non-zero
	// exit codes as hook failures. The user was already warned at session start.
	if repo, err := strategy.OpenRepository(ctx); err == nil && strategy.IsEmptyRepository(repo) {
		prepareSpan.End()
		logging.Info(logCtx, "skipping checkpoint - will activate after first commit")
		return nil
	}
	prepareSpan.End()

	// Create session metadata directory
	_, copySpan := perf.Start(ctx, "copy_transcript")
	sessionDir := paths.SessionMetadataDirFromSessionID(sessionID)
	sessionDirAbs, err := paths.AbsPath(ctx, sessionDir)
	if err != nil {
		sessionDirAbs = sessionDir
	}
	if err := os.MkdirAll(sessionDirAbs, 0o750); err != nil {
		copySpan.RecordError(err)
		copySpan.End()
		return fmt.Errorf("failed to create session directory: %w", err)
	}

	// Copy transcript to session directory
	transcriptData, err := ag.ReadTranscript(transcriptRef)
	if err != nil {
		copySpan.RecordError(err)
		copySpan.End()
		return fmt.Errorf("failed to read transcript: %w", err)
	}
	logFile := filepath.Join(sessionDirAbs, paths.TranscriptFileName)
	if err := os.WriteFile(logFile, transcriptData, 0o600); err != nil {
		copySpan.RecordError(err)
		copySpan.End()
		return fmt.Errorf("failed to write transcript: %w", err)

package copilotcli

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/paths"
)

// HooksFileName is the hooks file managed by Entire for Copilot CLI.
const HooksFileName = "entire.json"

// hooksDir is the directory within the repo where Copilot CLI looks for hook configs.
const hooksDir = ".github/hooks"

// entireHookPrefixes are command prefixes that identify Entire hooks in the bash field.
var entireHookPrefixes = []string{
	"entire ",
	`go run "$(git rev-parse --show-toplevel)"/cmd/entire/main.go `,
}

// hookConfigKey maps our kebab-case hook names to camelCase JSON keys.
var hookConfigKey = map[string]string{
	HookNameUserPromptSubmitted: "userPromptSubmitted",
	HookNameSessionStart:        "sessionStart",
	HookNameAgentStop:           "agentStop",
	HookNameSessionEnd:          "sessionEnd",
	HookNameSubagentStop:        "subagentStop",
	HookNamePreToolUse:          "preToolUse",
	HookNamePostToolUse:         "postToolUse",
	HookNameErrorOccurred:       "errorOccurred",
}

// InstallHooks installs Copilot CLI hooks in .github/hooks/entire.json.
// If force is true, removes existing Entire hooks before installing.
// Returns the number of hooks installed.
// Unknown top-level fields and hook types are preserved on round-trip.
func (c *CopilotCLIAgent) InstallHooks(ctx context.Context, localDev bool, force bool) (int, error) {
	worktreeRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		worktreeRoot = "."
	}

	hooksPath := filepath.Join(worktreeRoot, hooksDir, HooksFileName)

	// Use raw maps to preserve unknown fields on round-trip
	var rawFile map[string]json.RawMessage
	var rawHooks map[string]json.RawMessage

	existingData, readErr := os.ReadFile(hooksPath) //nolint:gosec // path is constructed from repo root + fixed path
	switch {
	case readErr == nil:
		if err := json.Unmarshal(existingData, &rawFile); err != nil {
			return 0, fmt.Errorf("failed to parse existing %s: %w", HooksFileName, err)
		}
		if hooksRaw, ok := rawFile["hooks"]; ok {
			if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
				return 0, fmt.Errorf("failed to parse hooks in %s: %w", HooksFileName, err)
			}
		}
		if _, ok := rawFile["version"]; !ok {
			rawFile["version"] = json.RawMessage(`1`)
		}
	case errors.Is(readErr, os.ErrNotExist):
		rawFile = map[string]json.RawMessage{
			"version": json.RawMessage(`1`),
		}
	default:
		return 0, fmt.Errorf("failed to read %s: %w", HooksFileName, readErr)
	}

	if rawHooks == nil {
		rawHooks = make(map[string]json.RawMessage)
	}

	// Parse existing entries for each hook type we manage
	hookEntries := make(map[string][]CopilotHookEntry)
	for _, hookName := range c.HookNames() {
		key := hookConfigKey[hookName]
		var entries []CopilotHookEntry
		if err := parseCopilotHookType(rawHooks, key, &entries); err != nil {
			return 0, fmt.Errorf("failed to parse %s hooks: %w", key, err)
		}
		hookEntries[hookName] = entries
	}

	// If force, remove existing Entire hooks first
	if force {
		for hookName, entries := range hookEntries {
			hookEntries[hookName] = removeEntireHooks(entries)
		}
	}

	// Define command prefix
	var cmdPrefix string
	if localDev {
		cmdPrefix = `go run "$(git rev-parse --show-toplevel)"/cmd/entire/main.go hooks copilot-cli `
	} else {
		cmdPrefix = "entire hooks copilot-cli "
	}

	count := 0

	// Add hooks that don't already exist
	for _, hookName := range c.HookNames() {
		cmd := cmdPrefix + hookName
		entries := hookEntries[hookName]
		if !hookBashExists(entries, cmd) {
			entries = append(entries, CopilotHookEntry{
				Type:    "command",
				Bash:    cmd,
				Comment: "Entire CLI",
			})
			hookEntries[hookName] = entries
			count++
		}
	}

	if count == 0 {
		return 0, nil
	}

	// Marshal modified hook types back into rawHooks
	for _, hookName := range c.HookNames() {
		key := hookConfigKey[hookName]
		if err := marshalCopilotHookType(rawHooks, key, hookEntries[hookName]); err != nil {
			return 0, fmt.Errorf("failed to marshal %s hooks: %w", key, err)
		}
	}

	// Marshal hooks and update raw file
	hooksJSON, err := json.Marshal(rawHooks)
	if err != nil {
		return 0, fmt.Errorf("failed to marshal hooks: %w", err)
	}
	rawFile["hooks"] = hooksJSON

	// Write to file
	if err := os.MkdirAll(filepath.Dir(hooksPath), 0o750); err != nil {
		return 0, fmt.Errorf("failed to create %s directory: %w", hooksDir, err)
	}

	output, err := jsonutil.MarshalIndentWithNewline(rawFile, "", "  ")
	if err != nil {
		return 0, fmt.Errorf("failed to marshal %s: %w", HooksFileName, err)
	}

	if err := os.WriteFile(hooksPath, output, 0o600); err != nil {
		return 0, fmt.Errorf("failed to write %s: %w", HooksFileName, err)
	}

	return count, nil
}

// UninstallHooks removes Entire hooks from Copilot CLI's entire.json.
// Unknown top-level fields and hook types are preserved on round-trip.
func (c *CopilotCLIAgent) UninstallHooks(ctx context.Context) error {
	worktreeRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		worktreeRoot = "."
	}
	hooksPath := filepath.Join(worktreeRoot, hooksDir, HooksFileName)
	data, err := os.ReadFile(hooksPath) //nolint:gosec // path is constructed from repo root + fixed path
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return nil // No hooks file means nothing to uninstall
		}
		return fmt.Errorf("failed to read %s: %w", HooksFileName, err)
	}

	var rawFile map[string]json.RawMessage
	if err := json.Unmarshal(data, &rawFile); err != nil {
		return fmt.Errorf("failed to parse %s: %w", HooksFileName, err)
	}

	var rawHooks map[string]json.RawMessage
	if hooksRaw, ok := rawFile["hooks"]; ok {
		if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
			return fmt.Errorf("failed to parse hooks in %s: %w", HooksFileName, err)
		}
	}
	if rawHooks == nil {
		rawHooks = make(map[string]json.RawMessage)
	}

	// Parse and remove Entire hooks from each hook type we manage
	for _, hookName := range c.HookNames() {
		key := hookConfigKey[hookName]
		var entries []CopilotHookEntry
		if err := parseCopilotHookType(rawHooks, key, &entries); err != nil {
			return fmt.Errorf("failed to parse %s hooks: %w", key, err)
		}
		entries = removeEntireHooks(entries)
		if err := marshalCopilotHookType(rawHooks, key, entries); err != nil {
			return fmt.Errorf("failed to marshal %s hooks: %w", key, err)
		}
	}

	// Marshal hooks back (preserving unknown hook types)
	if len(rawHooks) > 0 {
		hooksJSON, err := json.Marshal(rawHooks)
		if err != nil {
			return fmt.Errorf("failed to marshal hooks: %w", err)
		}
		rawFile["hooks"] = hooksJSON
	} else {
		delete(rawFile, "hooks")
	}

	// Write back
	output, err := jsonutil.MarshalIndentWithNewline(rawFile, "", "  ")
	if err != nil {

	logging.Info(logCtx, "context compaction detected")
	return nil
}

// handleLifecycleSessionEnd handles session end: marks the session as ended.
func handleLifecycleSessionEnd(ctx context.Context, ag agent.Agent, event *agent.Event) error {
	logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
	logging.Info(logCtx, "session-end",
		slog.String("event", event.Type.String()),
		slog.String("session_id", event.SessionID),
	)

	if event.SessionID == "" {
		return nil // No session to update
	}

	// Note: We intentionally don't clean up cached transcripts here.
	// Post-session commits (carry-forward in ENDED phase) may still need
	// the transcript to extract file changes. Cleanup is handled by
	// `entire clean` or when the session state is fully removed.

	if err := markSessionEnded(ctx, event, event.SessionID); err != nil {
		logging.Warn(logCtx, "failed to mark session ended",
			slog.String("error", err.Error()))
		// Don't attempt eager condense if we couldn't even mark the session ended —
		// the session state may be in an inconsistent state.
		return nil
	}

	// Eagerly condense session data so PostCommit doesn't have to process it.
	// This prevents zombie ENDED sessions from accumulating and causing O(N)
	// overhead on every future commit (GitHub issue #591).
	// Fail-open: if this fails, PostCommit will still process it on the next commit.
	strat := GetStrategy(ctx)
	if err := strat.CondenseAndMarkFullyCondensed(ctx, event.SessionID); err != nil {
		logging.Warn(logCtx, "eager condense on session stop failed",
			slog.String("session_id", event.SessionID),
			slog.String("error", err.Error()))
	}

	return nil
}

